"""Throwaway final-regression helper; not shipped in AMKernel."""
import hashlib
import json
from pathlib import Path
import sys
from types import SimpleNamespace

ROOT = Path('$SOURCE_ROOT')
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))
from tests.e2e.skill_behavior import RuntimeContext, _run_copilot, _payload_from_result, _final_json, _terminate_owned_runners
import tests.e2e.skill_behavior as behavior


def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()


def run_native(project, cli, prompt, base, env, timeout=420):
    context = RuntimeContext(
        options=SimpleNamespace(copilot=cli, model='gpt-6.1-sol', timeout=timeout),
        base=base, project=project, home=base / 'copilot', env=env,
        token=env['COPILOT_GITHUB_TOKEN'], temp_evidence={}, evidence={},
        commands=[], isolation_before={},
    )
    payload_by_call = {}
    argument_hashes = {}
    code_hashes = {}
    original_normalize = behavior.normalize_copilot_events
    def observe(events):
        calls, servers, final = original_normalize(events)
        for event in events:
            data = event.get('data')
            if not isinstance(data, dict):
                continue
            call_id = data.get('toolCallId')
            if not isinstance(call_id, str):
                continue
            if event.get('type') == 'tool.execution_start':
                argument_hashes[call_id] = digest(json.dumps(data.get('arguments'), sort_keys=True))
                arguments = data.get('arguments')
                if isinstance(arguments, dict) and isinstance(arguments.get('code'), str):
                    code_hashes[call_id] = digest(arguments['code'])
            elif event.get('type') == 'tool.execution_complete':
                payload = _payload_from_result(data.get('result'))
                if isinstance(payload, dict) and 'kernelState' in payload:
                    payload_by_call[call_id] = payload
        return calls, servers, final
    behavior.normalize_copilot_events = observe
    try:
        calls, servers, final, details = _run_copilot(context, prompt)
    finally:
        behavior.normalize_copilot_events = original_normalize
    process = details['process']
    final_cleanup = _terminate_owned_runners(context, 'final-regression')
    if final_cleanup:
        process['runnerCleanupFinal'] = final_cleanup
    cleanup_keys = {'runnerPid', 'reason', 'signalSent', 'observedExit', 'identityMismatch', 'signal', 'target', 'error'}
    for key in ('runnerCleanup', 'runnerCleanupFinal'):
        if isinstance(process.get(key), list):
            process[key] = [{k: v for k, v in item.items() if k in cleanup_keys} for item in process[key] if isinstance(item, dict)]
    records = []
    payloads = []
    for call in calls:
        arguments = call.get('arguments')
        arguments = arguments if isinstance(arguments, dict) else {}
        payload = payload_by_call.get(str(call.get('toolCallId')))
        if payload is not None:
            payloads.append(payload)
        item = {
            'toolName': call.get('toolName'),
            'mcpToolName': call.get('mcpToolName'),
            'mcpConfigSource': call.get('mcpConfigSource'),
            'argumentsSha256': argument_hashes.get(str(call.get('toolCallId'))),
            'codeSha256': code_hashes.get(str(call.get('toolCallId'))),
            'success': call.get('success') is True,
        }
        if call.get('toolName') == 'skill':
            name = arguments.get('skill')
            if isinstance(name, str) and name in {'amkernel', 'setup-mac2', 'setup-uiautomator2', 'setup-xcuitest', 'xcuitest-real-device-config'}:
                item['skill'] = name
        if payload is not None:
            item.update({k: payload.get(k) for k in ('status', 'kernelState', 'executionCount', 'durationMs')})
            for key in ('stdout', 'stderr'):
                text = payload.get(key)
                if isinstance(text, str):
                    item[key + 'Sha256'] = digest(text)
                    item[key + 'Bytes'] = len(text.encode())
            error = payload.get('error')
            if isinstance(error, dict):
                item['errorType'] = error.get('type')
        records.append(item)
    safe_final = {}
    parsed = _final_json(final)
    if parsed is not None:
        enums = {
            'taskOutcome': {'completed', 'blocked', 'failed', 'ready-for-next-step', 'approval-required'},
            'stateRestoration': {'restored', 'unchanged', 'not-needed', 'not-applicable', 'failed', 'unknown'},
            'sessionCleanup': {'cleaned', 'not-created', 'not-needed', 'not-applicable', 'failed', 'unknown'},
            'serverCleanup': {'not-owned', 'preserved', 'not-started', 'not-needed', 'not-applicable', 'failed', 'unknown'},
        }
        for key, allowed in enums.items():
            value = parsed.get(key)
            if isinstance(value, str) and value in allowed:
                safe_final[key] = value
    safe = {
        'process': process,
        'calls': records,
        'finalReportSha256': digest(final),
        'finalStatus': safe_final,
        'observedCompletedAlive': bool(payloads) and all(p.get('status') == 'completed' and p.get('kernelState') == 'alive' for p in payloads),
        'mainSkillLoaded': any(c.get('skill') == 'amkernel' and c.get('success') is True for c in records),
        'limits': 'Only allowlisted status/identity evidence and hashes retained; raw code, output, final prose and stderr withheld.',
    }
    # Raw payloads are transient inputs to the caller's strict domain allowlist,
    # never retained by this helper.
    return safe, payloads, parsed


def serialize(record, token, replacements=()):
    text = json.dumps(record, ensure_ascii=False, indent=2)
    if token:
        text = text.replace(token, '[REDACTED_TOKEN]')
    for old, new in replacements:
        text = text.replace(str(old), new)
    return text + '\n'

#!/usr/bin/env python3
"""Throwaway actual Mac2 regression probe; not product code.

The only visible change this probe authorizes is launching/foregrounding the
real Calculator for read-only app-state and window queries through a real Mac2
session, followed by restoration and quit.  The Appium server and its WDA
children are task-owned; the native Copilot client and its Runner are owned by
native_evidence.run_native, which also terminates owned Runners on timeout.
"""
import argparse
import hashlib
import json
import os
import re
import shutil
import signal
import socket
import subprocess
import sys
import tempfile
import time
import urllib.request
from pathlib import Path

TOOL_DIR = Path(__file__).resolve().parent
if str(TOOL_DIR) not in sys.path:
    sys.path.insert(0, str(TOOL_DIR))
from native_evidence import run_native, serialize

CALCULATOR_BUNDLE = 'com.apple.calculator'
ELEMENT_KEY = 'element-6066-11e4-a52e-4f735466cecf'
WINDOW_QUERY_MARKER = 'XCUIElementTypeWindow'

state_code = (
    'ObjC.import("AppKit");'
    'var apps=$.NSWorkspace.sharedWorkspace.runningApplications;'
    'var found=[];'
    'for(var i=0;i<apps.count;i++){'
    'var a=apps.objectAtIndex(i);'
    'var b=ObjC.unwrap(a.bundleIdentifier);'
    'if(b==="com.apple.calculator"){found.push({bundleId:b,pid:a.processIdentifier,hidden:a.hidden});}'
    '}'
    'var front=$.NSWorkspace.sharedWorkspace.frontmostApplication;'
    'var frontId=null;'
    'try{frontId=front?ObjC.unwrap(front.bundleIdentifier):null;}catch(e){frontId=null;}'
    'JSON.stringify({calculator:found,frontmostBundleId:frontId});'
)

parser = argparse.ArgumentParser()
parser.add_argument('--project', type=Path, required=True)
parser.add_argument('--copilot', type=Path, required=True)
parser.add_argument('--output', type=Path, required=True)
args = parser.parse_args()

base = Path(tempfile.mkdtemp(prefix='amkernel-mac2-agent-'))
project = args.project.resolve()
output = Path(args.output)


def digest(text):
    return hashlib.sha256(text.encode()).hexdigest()


def ui_state():
    completed = subprocess.run(
        ['osascript', '-l', 'JavaScript', '-e', state_code],
        capture_output=True, text=True, check=True, timeout=15,
    )
    value = json.loads(completed.stdout)
    if not isinstance(value, dict):
        raise ValueError('unexpected desktop observation shape')
    calculator = value.get('calculator')
    frontmost = value.get('frontmostBundleId')
    if not isinstance(calculator, list) or not (frontmost is None or isinstance(frontmost, str)):
        raise ValueError('unexpected desktop observation fields')
    normalized = []
    for item in calculator:
        if (
            not isinstance(item, dict)
            or item.get('bundleId') != CALCULATOR_BUNDLE
            or not isinstance(item.get('pid'), int)
        ):
            raise ValueError('unexpected calculator observation fields')
        hidden = item.get('hidden')
        if not isinstance(hidden, bool):
            if hidden in (0, 1):
                hidden = bool(hidden)
            else:
                raise ValueError('unexpected calculator visibility field')
        normalized.append({'bundleId': CALCULATOR_BUNDLE, 'pid': item['pid'], 'hidden': hidden})
    normalized.sort(key=lambda item: item['pid'])
    return {'calculator': normalized, 'frontmostBundleId': frontmost}


def free_port():
    with socket.socket() as sock:
        sock.bind(('127.0.0.1', 0))
        return sock.getsockname()[1]


def http_json(url):
    with urllib.request.urlopen(url, timeout=5) as response:
        return json.load(response)


def read_session_ids(endpoint):
    payload = http_json(endpoint + '/appium/sessions')
    sessions = payload.get('value') if isinstance(payload, dict) else None
    if not isinstance(sessions, list):
        return None
    ids = []
    for item in sessions:
        if not isinstance(item, dict) or not isinstance(item.get('id'), str):
            return None
        ids.append(item['id'])
    return ids


def parse_json_prefix(text):
    text = (text or '').strip()
    if not text:
        return None
    try:
        value, _end = json.JSONDecoder().raw_decode(text)
    except (TypeError, ValueError):
        return None
    return value


HTTP_START = re.compile(r'\[HTTP\]\s+-->\s+(GET|POST|DELETE)\s+(\S+)(?:\s+(.*))?$')
HTTP_END = re.compile(r'\[HTTP\]\s+<--\s+(GET|POST|DELETE)\s+(\S+)\s+(\d{3})\b')
CALLING = re.compile(r'Calling [\w.$]+\.(\w+)\(\) with args: (.*)$')
RESPONDING = re.compile(r'Responding to client with driver\.(\w+)\(\) result: (.*)$')
PROXY_OK = re.compile(r'Got response with status (\d+): (.*)$')
SESSION_CREATED = re.compile(r'Session created with session id: (\S+)')
SESSION_ROUTE = re.compile(r'^/session/([^/]+)(?:/|$)')


def parse_transactions(log_path):
    try:
        handle = log_path.open('r', encoding='utf-8', errors='replace')
    except OSError:
        return None
    transactions = []
    current = None
    with handle:
        for raw in handle:
            line = raw.rstrip('\n')
            start = HTTP_START.search(line)
            if start:
                current = {
                    'method': start.group(1),
                    'path': start.group(2),
                    'request': parse_json_prefix(start.group(3)),
                    'calling': [],
                    'responding': [],
                    'proxy': [],
                    'sessionCreated': None,
                    'status': None,
                }
                transactions.append(current)
                continue
            if current is None:
                continue
            end = HTTP_END.search(line)
            if end and current['status'] is None:
                current['status'] = int(end.group(3))
                continue
            if current['status'] is not None:
                continue
            match = SESSION_CREATED.search(line)
            if match:
                current['sessionCreated'] = match.group(1)
            match = CALLING.search(line)
            if match:
                current['calling'].append({'command': match.group(1), 'value': parse_json_prefix(match.group(2))})
            match = RESPONDING.search(line)
            if match:
                current['responding'].append({'command': match.group(1), 'value': parse_json_prefix(match.group(2))})
            match = PROXY_OK.search(line)
            if match:
                current['proxy'].append({'status': int(match.group(1)), 'value': parse_json_prefix(match.group(2))})
    return transactions


def cap_pairs(value):
    pairs = []

    def walk(node):
        if isinstance(node, dict):
            for key, item in node.items():
                pairs.append((key, item))
                walk(item)
        elif isinstance(node, list):
            for item in node:
                walk(item)

    walk(value)
    return pairs


def cap_identity(value):
    pairs = cap_pairs(value)

    def has(suffix, expected):
        return any(
            isinstance(key, str) and key.lower().endswith(suffix)
            and isinstance(item, str) and item == expected
            for key, item in pairs
        )

    return {
        'automationNameMac2': has('automationname', 'Mac2'),
        'calculatorBundleId': has('bundleid', CALCULATOR_BUNDLE),
        'platformMac': any(
            isinstance(key, str) and key.lower() == 'platformname'
            and isinstance(item, str) and item.lower() == 'mac'
            for key, item in pairs
        ),
    }


def normalize_script(value):
    if not isinstance(value, str):
        return None
    return re.sub(r'\s+', ' ', value.strip()).lower()


def session_id_of(path):
    match = SESSION_ROUTE.match(path)
    return match.group(1) if match else None


def bundle_argument_ok(arguments):
    if not isinstance(arguments, list) or len(arguments) != 1:
        return False
    item = arguments[0]
    if isinstance(item, str):
        return item == CALCULATOR_BUNDLE
    if isinstance(item, dict):
        return any(
            isinstance(key, str) and key.lower() == 'bundleid' and value == CALCULATOR_BUNDLE
            for key, value in item.items()
        )
    return False


def parse_protocol(log_path):
    transactions = parse_transactions(log_path)
    if transactions is None:
        return {'view': {'parseComplete': False}, 'matched': {}, 'sessionId': None, 'sessionIds': set()}

    session_ids = {sid for txn in transactions if (sid := session_id_of(txn['path']))}

    create = None
    for txn in transactions:
        if txn['method'] != 'POST' or txn['path'] != '/session' or txn['status'] != 200:
            continue
        if not txn['sessionCreated'] or not isinstance(txn['request'], dict):
            continue
        request_identity = cap_identity(txn['request'])
        responses = [item['value'] for item in txn['responding'] if item['command'] == 'createSession']
        response_identity = cap_identity(responses[-1]) if responses else cap_identity(None)
        create = {
            'sessionId': txn['sessionCreated'],
            'status': txn['status'],
            'request': request_identity,
            'response': response_identity,
        }
        break

    sid = create['sessionId'] if create else None
    request_ok = bool(create and all(create['request'].values()))
    response_ok = bool(create and create['response']['automationNameMac2'] and create['response']['calculatorBundleId'])

    query = {'observed': False, 'status': None, 'scriptOk': False, 'bundleArgumentOk': False, 'foregroundValue': None, 'foregroundOk': False}
    query_ok = False
    if sid:
        for txn in transactions:
            match = re.match(r'^/session/([^/]+)/execute/sync$', txn['path'])
            if not match or match.group(1) != sid or txn['method'] != 'POST' or txn['status'] != 200:
                continue
            request = txn['request'] if isinstance(txn['request'], dict) else {}
            script_ok = normalize_script(request.get('script')) == 'macos: queryappstate'
            arguments = request.get('args')
            argument_ok = bundle_argument_ok(arguments)
            values = [item['value'] for item in txn['responding'] if item['command'] == 'execute']
            observed_value = values[-1] if values else None
            if isinstance(observed_value, dict):
                observed_value = observed_value.get('value', observed_value.get('state'))
            foreground_value = observed_value if isinstance(observed_value, int) else None
            foreground = foreground_value == 4
            candidate = {
                'observed': True, 'status': txn['status'], 'scriptOk': script_ok,
                'bundleArgumentOk': argument_ok, 'foregroundValue': foreground_value,
                'foregroundOk': foreground,
            }
            if script_ok and argument_ok and foreground:
                query = candidate
                query_ok = True
                break
            if not query['observed']:
                query = candidate

    elements = {'observed': False, 'status': None, 'windowQuery': False, 'count': None, 'nonEmptyElementList': False}
    elements_ok = False
    handles = {'observed': False, 'status': None, 'nonEmptyHandleList': False, 'count': None}
    handles_ok = False
    if sid:
        for txn in transactions:
            match = re.match(r'^/session/([^/]+)/elements$', txn['path'])
            if not match or match.group(1) != sid or txn['method'] != 'POST' or txn['status'] != 200:
                continue
            request = txn['request'] if isinstance(txn['request'], dict) else {}
            query_value = request.get('value')
            window_query = isinstance(query_value, str) and WINDOW_QUERY_MARKER in query_value
            values = [item['value'] for item in txn['responding'] if item['command'] == 'findElements']
            observed_value = values[-1] if values else None
            count = len(observed_value) if isinstance(observed_value, list) else None
            non_empty = (
                isinstance(observed_value, list)
                and len(observed_value) > 0
                and all(isinstance(item, dict) and isinstance(item.get(ELEMENT_KEY), str) for item in observed_value)
            )
            candidate = {
                'observed': True, 'status': txn['status'], 'windowQuery': window_query,
                'count': count, 'nonEmptyElementList': non_empty,
            }
            if window_query and non_empty:
                elements = candidate
                elements_ok = True
                break
            if not elements['observed']:
                elements = candidate
        for txn in transactions:
            match = re.match(r'^/session/([^/]+)/window/handles$', txn['path'])
            if not match or match.group(1) != sid or txn['method'] != 'GET' or txn['status'] != 200:
                continue
            observed_value = None
            for item in txn['proxy']:
                if item['status'] == 200 and isinstance(item['value'], dict) and isinstance(item['value'].get('value'), list):
                    observed_value = item['value']['value']
            for item in txn['responding']:
                if item['command'] == 'getWindowHandles' and isinstance(item['value'], list):
                    observed_value = item['value']
            non_empty = (
                isinstance(observed_value, list)
                and len(observed_value) > 0
                and all(isinstance(entry, str) for entry in observed_value)
            )
            candidate = {
                'observed': True, 'status': txn['status'], 'nonEmptyHandleList': non_empty,
                'count': len(observed_value) if isinstance(observed_value, list) else None,
            }
            if non_empty:
                handles = candidate
                handles_ok = True
            elif not handles['observed']:
                handles = candidate

    delete = {'observed': False, 'status': None}
    delete_ok = False
    if sid:
        for txn in transactions:
            if txn['method'] == 'DELETE' and txn['path'] == f'/session/{sid}' and txn['status'] == 200:
                delete = {'observed': True, 'status': txn['status']}
                delete_ok = True
                break
            if txn['method'] == 'DELETE' and txn['path'] == f'/session/{sid}':
                delete = {'observed': True, 'status': txn['status']}

    view = {
        'parseComplete': True,
        'transactions': len(transactions),
        'sessionIdsObservedCount': len(session_ids),
        'createSession': {
            'observed': create is not None,
            'status': create['status'] if create else None,
            'requestAutomationNameMac2': create['request']['automationNameMac2'] if create else False,
            'requestCalculatorBundleId': create['request']['calculatorBundleId'] if create else False,
            'requestPlatformMac': create['request']['platformMac'] if create else False,
            'responseAutomationNameMac2': create['response']['automationNameMac2'] if create else False,
            'responseCalculatorBundleId': create['response']['calculatorBundleId'] if create else False,
            'responsePlatformMac': create['response']['platformMac'] if create else False,
            'sessionIdSha256': digest(sid) if sid else None,
        },
        'queryAppState': query,
        'windowElements': elements,
        'windowHandles': handles,
        'sessionDelete': delete,
        'singleSessionObserved': len(session_ids) == 1 and sid is not None and sid in session_ids,
        'listing': {
            'observed': False,
            'observedBeforeOwnedServerStop': False,
            'count': None,
            'qualifyingSessionListed': None,
            'idsSha256': None,
        },
    }
    matched = {
        'createSession': create is not None and request_ok and response_ok and bool(sid),
        'queryAppState': query_ok,
        'window': elements_ok or handles_ok,
        'singleSession': view['singleSessionObserved'],
        'sessionDelete': delete_ok,
    }
    return {'view': view, 'matched': matched, 'sessionId': sid, 'sessionIds': session_ids}


def port_closed(port):
    if port is None:
        return None
    with socket.socket() as sock:
        sock.settimeout(0.5)
        try:
            return sock.connect_ex(('127.0.0.1', port)) != 0
        except OSError:
            return None


def wait_port_closed(port, deadline_seconds=5.0):
    end = time.monotonic() + deadline_seconds
    while True:
        state = port_closed(port)
        if state is not False or time.monotonic() >= end:
            return state
        time.sleep(0.25)


def wait_group_gone(pgid, deadline_seconds=5.0):
    end = time.monotonic() + deadline_seconds
    while True:
        try:
            os.killpg(pgid, 0)
            gone = False
        except ProcessLookupError:
            gone = True
        except OSError:
            gone = None
        if gone is not False or time.monotonic() >= end:
            return gone
        time.sleep(0.25)


record = {
    'schemaVersion': 2,
    'scope': 'Actual installed native Copilot, actual Mac2/Calculator; no fixture, synthetic driver, arithmetic, or personal app contents',
    'status': 'not-qualified',
    'base': str(base),
    'project': str(project),
    'failedAt': None,
    'error': None,
    'before': None,
    'after': None,
    'cleanup': {
        'desktopRestored': 'unknown',
        'desktopLimits': (
            'Desktop restoration compares only JXA observations of running com.apple.calculator '
            'processes (bundleId, pid, hidden) and the frontmost bundle identifier at two instants; '
            'it makes no claim about other applications, window contents, focus within apps, or '
            'intermediate states.'
        ),
        'ownedServer': {
            'started': False, 'pid': None, 'pgid': None, 'groupOwned': None,
            'stopAttempted': False, 'exited': None, 'processGroupGone': None,
            'appiumPortClosed': None, 'wdaPortClosed': None,
        },
        'runner': {
            'entries': [],
            'observedGone': None,
            'limits': 'Runner evidence is the owned-runner termination report from native_evidence; '
                      'it is not inferred from the Appium server exit.',
        },
        'limits': 'No claim is made about unrelated system processes or external helpers.',
    },
    'server': None,
    'requestedIdentity': None,
    'native': None,
    'appium': None,
    'protocol': None,
    'qualification': None,
    'limits': (
        'No raw tool arguments, python_exec stdout/stderr, final prose, Appium log text, session '
        'capabilities, device inventory, or driver diagnostics are persisted; only allowlisted parsed '
        'protocol/session metadata, process identity, statuses, and SHA-256 hashes are retained.'
    ),
}

token = ''
server = None
log_handle = None
log_path = base / 'appium.log'
appium_port = None
wda_port = None
endpoint = None
observed_session_ids = None
session_listing_observed_before_stop = False
stage = 'initial-desktop-observation'

try:
    try:
        record['before'] = ui_state()
    except Exception as error:
        record['beforeObservationError'] = {'type': type(error).__name__, 'messageSha256': digest(str(error))}
        raise RuntimeError('initial desktop observation unavailable') from error

    stage = 'appium-discovery'
    appium = shutil.which('appium')
    if not appium:
        raise RuntimeError('No existing Appium executable; installation is not authorized')
    appium_home = Path(os.environ.get('APPIUM_HOME', str(Path.home() / '.appium'))).expanduser().resolve()
    wda_source = appium_home / 'node_modules/appium-mac2-driver/WebDriverAgentMac'
    if not wda_source.is_dir():
        raise RuntimeError('Existing Mac2 WebDriverAgentMac source is missing; driver installation is not authorized')

    stage = 'bootstrap-copy'
    bootstrap = base / 'WebDriverAgentMac'
    shutil.copytree(wda_source, bootstrap, ignore=shutil.ignore_patterns('build', 'DerivedData', '.git'))

    stage = 'server-start'
    appium_port, wda_port = free_port(), free_port()
    while wda_port == appium_port:
        wda_port = free_port()
    endpoint = f'http://127.0.0.1:{appium_port}'
    server_home = base / 'appium-home'
    server_home.mkdir()
    server_env = dict(os.environ, HOME=str(server_home), APPIUM_HOME=str(appium_home))
    server_env.pop('COPILOT_GITHUB_TOKEN', None)
    log_handle = log_path.open('w')
    server = subprocess.Popen(
        [appium, '--address', '127.0.0.1', '--port', str(appium_port), '--use-drivers', 'mac2',
         '--log-no-colors', '--log-level', 'debug', '--allow-insecure=*:session_discovery'],
