"""Task-owned final-regression platform prerequisite discovery (throwaway verification support).

Runs the real installed native Copilot/MCP client in an isolated home, asks it
to execute one task-owned read-only probe through the real amkernel
python_exec tool, then parses the actual MCP payloads against a strict schema.
Raw code, tool arguments, stdout/stderr, final prose, inventories, device
identifiers and tokens are never written to the evidence file.

This is discovery only. It never claims a platform session/scenario result.
"""
import argparse
import hashlib
import json
from pathlib import Path
import os
import re
import subprocess
import sys
import tempfile

TOOLS_DIR = Path(__file__).resolve().parent
sys.path.insert(0, str(TOOLS_DIR))
from native_evidence import run_native, serialize

PROBE_PATH = TOOLS_DIR / 'platform_readonly_probe.py'
ALLOWED_TOOLS = frozenset({'amkernel', 'amkernel-python_exec', 'skill', 'view'})
PERMITTED_SKILLS = frozenset(
    {'amkernel', 'setup-mac2', 'setup-uiautomator2', 'setup-xcuitest', 'xcuitest-real-device-config'}
)
PROBE_LIMITATIONS = frozenset(
    {
        'adb-binary-missing',
        'adb-server-not-preexisting',
        'android-target-counts-unknown',
        'device-inventory-unparseable',
        'devicectl-missing',
        'java-version-execution-unavailable',
        'sdk-root-missing',
        'simctl-missing',
        'simulator-inventory-unparseable',
        'xcode-not-selected',
    }
)
CONFIG_PATHS = [
    '~/.zshrc',
    '~/.zprofile',
    '~/.bashrc',
    '~/.bash_profile',
    '~/.mcp.json',
    '~/.copilot/config.json',
    '~/.copilot/mcp-config.json',
]

PLATFORM_GOALS = {
    'android': (
