def _snapshot():
    result = {}
    for raw in CONFIG_PATHS:
        path = Path(raw).expanduser()
        try:
            result[raw] = hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None
        except OSError:
            result[raw] = 'unreadable'
    return result


def _github_token():
    completed = subprocess.run(
        ['gh', 'auth', 'token'],
        capture_output=True,
        text=True,
        timeout=30,
        check=True,
    )
    token = completed.stdout.strip()
    if not token:
        raise RuntimeError('empty-token')
    return token


def _count(value):
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _optional_count(value):
    return value is None or _count(value)


def _boolean(value):
    return isinstance(value, bool)


def _keys(value, expected):
    return isinstance(value, dict) and set(value) == set(expected)


def _count_list(value):
    return isinstance(value, list) and all(_count(item) for item in value)


def _valid_android(facts):
    if not isinstance(facts, dict) or set(facts) != {'java', 'sdk', 'adb', 'adbServer', 'targets'}:
        return False
    java = facts['java']
    if not _keys(
        java,
        {'candidates', 'executed', 'succeeded', 'majorVersions', 'defaultExecuted', 'defaultMajor'},
    ):
        return False
    if not (_count(java['candidates']) and _count(java['executed']) and _count(java['succeeded'])):
        return False
    if not _count_list(java['majorVersions']):
        return False
    if not (_boolean(java['defaultExecuted']) and _optional_count(java['defaultMajor'])):
        return False
    sdk = facts['sdk']
    if not _keys(sdk, {'envConfigured', 'defaultRootPresent', 'rootPresent'}):
        return False
    if not all(_boolean(sdk[key]) for key in sdk):
        return False
    adb = facts['adb']
    if not _keys(adb, {'present', 'versionExecuted', 'versionParsed', 'major', 'minor', 'build'}):
        return False
    if not all(_boolean(adb[key]) for key in ('present', 'versionExecuted', 'versionParsed')):
        return False
    if not all(_optional_count(adb[key]) for key in ('major', 'minor', 'build')):
        return False
    server = facts['adbServer']
    if not (_keys(server, {'preexistingListening'}) and _boolean(server['preexistingListening'])):
        return False
    targets = facts['targets']
    if targets is not None:
        if not _keys(
            targets,
            {'known', 'total', 'device', 'emulator', 'offline', 'unauthorized', 'other'},
        ):
            return False
        if not _boolean(targets['known']):
            return False
        if not all(_count(targets[key]) for key in targets if key != 'known'):
            return False
    return True


def _valid_xcode(xcode):
    if not _keys(
        xcode,
        {'selectExecuted', 'selected', 'buildExecuted', 'versionParsed', 'major', 'minor'},
    ):
        return False
    if not all(
        _boolean(xcode[key])
        for key in ('selectExecuted', 'selected', 'buildExecuted', 'versionParsed')
    ):
        return False
    return _optional_count(xcode['major']) and _optional_count(xcode['minor'])


def _valid_ios_simulator(facts):
    if not isinstance(facts, dict) or set(facts) != {'xcode', 'simctl', 'runtimes', 'devices'}:
        return False
    if not _valid_xcode(facts['xcode']):
        return False
    simctl = facts['simctl']
    if not _keys(simctl, {'present', 'listExecuted', 'parseable'}):
        return False
    if not all(_boolean(simctl[key]) for key in simctl):
        return False
    runtimes = facts['runtimes']
    if not _keys(runtimes, {'total', 'available', 'unavailable'}):
        return False
    if not all(_optional_count(runtimes[key]) for key in runtimes):
        return False
    devices = facts['devices']
    if not _keys(devices, {'total', 'booted', 'shutdown', 'available', 'unavailable'}):
        return False
    return all(_optional_count(devices[key]) for key in devices)


def _valid_ios_device(facts):
    if not isinstance(facts, dict) or set(facts) != {'xcode', 'devicectl'}:
        return False
    if not _valid_xcode(facts['xcode']):
        return False
    devicectl = facts['devicectl']
    if not _keys(devicectl, {'present', 'listExecuted', 'parseable', 'countsKnown', 'devices'}):
        return False
    if not all(
        _boolean(devicectl[key])
        for key in ('present', 'listExecuted', 'parseable', 'countsKnown')
    ):
        return False
    devices = devicectl['devices']
    if not _keys(devices, {'total', 'connected', 'paired', 'unavailable', 'unknown'}):
        return False
    return all(_optional_count(devices[key]) for key in devices)


VALIDATORS = {
    'android': _valid_android,
    'ios-simulator': _valid_ios_simulator,
    'ios-device': _valid_ios_device,
}


def _valid_probe(value, platform):
    if not isinstance(value, dict) or set(value) != {'schemaVersion', 'platform', 'facts', 'limitations'}:
        return False
    if value['schemaVersion'] != 1 or value['platform'] != platform:
        return False
    limitations = value['limitations']
    if not (
        isinstance(limitations, list)
        and all(isinstance(item, str) and item in PROBE_LIMITATIONS for item in limitations)
    ):
        return False
    return VALIDATORS[platform](value['facts'])


def _json_objects(text):
    decoder = json.JSONDecoder()
    for match in re.finditer(r'\{', text):
        try:
            value, _ = decoder.raw_decode(text[match.start():])
        except json.JSONDecodeError:
            continue
        if isinstance(value, dict):
            yield value


def _collect_probe(payloads, platform):
    accepted = []
    rejected = 0
    for payload in payloads:
        text = payload.get('stdout') if isinstance(payload, dict) else None
        if not isinstance(text, str):
            continue
        for candidate in _json_objects(text):
            if candidate.get('schemaVersion') != 1 or candidate.get('platform') != platform:
                continue
            if _valid_probe(candidate, platform):
                accepted.append(candidate)
            else:
                rejected += 1
    return accepted, rejected


def _classify(platform, facts):
    blockers = []
    if platform == 'android':
        java = facts['java']
        sdk = facts['sdk']
        adb = facts['adb']
        targets = facts['targets']
        if java['succeeded'] < 1:
            blockers.append('java-unavailable')
        if not sdk['rootPresent']:
            blockers.append('android-sdk-root-missing')
        if not adb['present']:
            blockers.append('adb-binary-missing')
        elif not adb['versionExecuted']:
            blockers.append('adb-version-execution-failed')
        elif not adb['versionParsed']:
            blockers.append('adb-version-parse-failed')
        if not facts['adbServer']['preexistingListening']:
            blockers.append('adb-server-not-preexisting')
        if targets is None or not targets.get('known'):
            blockers.append('android-target-counts-unknown')
        elif targets['total'] < 1:
            blockers.append('android-targets-zero')
        elif targets['device'] + targets['emulator'] < 1:
            blockers.append('android-targets-not-online')
    elif platform == 'ios-simulator':
        if not facts['xcode']['selected']:
            blockers.append('xcode-not-selected')
        elif not facts['xcode']['versionParsed']:
            blockers.append('xcode-version-unavailable')
        if not facts['simctl']['present']:
            blockers.append('simctl-missing')
        elif not facts['simctl']['parseable']:
            blockers.append('simulator-inventory-unparseable')
        else:
            if facts['runtimes']['available'] is None:
                blockers.append('simulator-runtime-counts-unknown')
            elif facts['runtimes']['available'] < 1:
                blockers.append('simulator-runtimes-zero')
            if facts['devices']['total'] is None:
                blockers.append('simulator-device-counts-unknown')
            elif facts['devices']['total'] < 1:
                blockers.append('simulator-devices-zero')
    else:
        if not facts['xcode']['selected']:
            blockers.append('xcode-not-selected')
        elif not facts['xcode']['versionParsed']:
            blockers.append('xcode-version-unavailable')
        devicectl = facts['devicectl']
        devices = devicectl['devices']
        if not devicectl['present']:
            blockers.append('devicectl-missing')
        elif not devicectl['parseable'] or not devicectl['countsKnown']:
            blockers.append('device-inventory-unparseable')
        else:
            if devices['total'] is None:
                blockers.append('physical-device-counts-unknown')
            elif devices['total'] < 1:
                blockers.append('physical-devices-zero')
            else:
                if devices['connected'] is None:
                    blockers.append('physical-device-counts-unknown')
                elif devices['connected'] < 1:
                    blockers.append('physical-device-connected-zero')
                if devices['paired'] is None:
                    blockers.append('physical-device-counts-unknown')
                elif devices['paired'] < 1:
                    blockers.append('physical-device-paired-zero')
    return ('blocked' if blockers else 'ready-for-next-step'), sorted(set(blockers))


def _probe_code(platform):
    return (
        'import json, hashlib; probe = %r; ns = {}; '
        'source = open(probe, "rb").read(); '
        'assert hashlib.sha256(source).hexdigest() == %r; '
        'exec(compile(source, probe, "exec"), ns); '
        'print(json.dumps(ns["probe_json"](%r), sort_keys=True))'
    ) % (str(PROBE_PATH), hashlib.sha256(PROBE_PATH.read_bytes()).hexdigest(), platform)


def _prompt(platform):
    invocation = _probe_code(platform)
    return ' '.join(
        [
            'Goal: ordered final real-platform regression prerequisite discovery on this actual macOS host.',
            'This is not a platform scenario or session check; discovery alone is never scenario success.',
            'Use the installed amkernel Skill and the installed official platform Skill(s) for this platform.',
            PLATFORM_GOALS[platform],
            'Run the task-owned read-only probe exactly once, and only through the real amkernel python_exec tool.',
            'Use exactly this code inside python_exec: ' + invocation,
            'The python_exec result must contain the printed probe JSON unchanged; do not reformat it and do not supplement it with raw command output.',
            'Probe output contract: one JSON object with schemaVersion 1, platform, facts (booleans, counts, parsed version numbers, null when unknown) and limitations (fixed canonical labels). It is the only accepted host-prerequisite evidence source.',
            'Do not run any other discovery command, tool or execution inside python_exec, and do not retry with alternate mechanisms.',
            'If the probe cannot execute or its output is invalid, report taskOutcome "blocked"; never fabricate, infer, prefill or convert unknown facts into zero.',
            'Do not install anything, start an ADB server or emulator, boot/create/pair a simulator or device, accept permissions, or mutate any configuration, session, service or device state.',
            'Return one final JSON object with: taskOutcome ("blocked" or "ready-for-next-step"), targetPlatform, probeExecuted (boolean), probeSchemaVersion (1 or null), blockers (short canonical labels or an empty list), stateRestoration, sessionCleanup, serverCleanup.',
            'No platform session or server was authorized: use "not-applicable" or "not-needed" and never claim cleanup success.',
            'Do not include paths, device names, serials, UDIDs, inventories, command output or error messages in the final JSON.',
            '"ready-for-next-step" means discovery observed the prerequisites; it is not a passed scenario.',
        ]
    )


def _base_record(platform):
    return {
        'schemaVersion': 2,
        'scope': 'Actual installed native Copilot read-only platform prerequisite discovery; no platform session/scenario qualification',
        'platform': platform,
        'qualification': 'not-qualified; discovery only; no platform session/scenario performed',
        'probe': {
            'name': 'platform_readonly_probe.py',
            'schemaVersion': 1,
            'sourceSha256': hashlib.sha256(PROBE_PATH.read_bytes()).hexdigest(),
            'execution': 'real amkernel python_exec only',
            'contract': 'strict allowlist: booleans, counts, parsed version numbers, canonical labels',
        },
        'evidenceLimits': (
            'Only allowlisted tool/status identity, hashes and schema-validated probe facts are retained. '
            'Raw code, tool arguments, stdout, stderr, final prose, device identifiers, inventories and '
            'credentials are withheld. Probe evidence proves the parsed shape of a real python_exec result, '
            'not provenance beyond the permitted tool boundary.'
        ),
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--platform', choices=['android', 'ios-simulator', 'ios-device'], required=True)
    parser.add_argument('--project', type=Path, required=True)
    parser.add_argument('--copilot', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()

    base = Path(tempfile.mkdtemp(prefix='amkernel-platform-preflight-'))
    client_home = base / 'copilot'
    client_home.mkdir(parents=True, exist_ok=True)
    project = args.project.resolve()
    (client_home / 'config.json').write_text(
        json.dumps({'trustedFolders': [str(project)]}), encoding='utf-8'
    )
    record = _base_record(args.platform)
    record['sourceSha256'] = {
        path.name: hashlib.sha256(path.read_bytes()).hexdigest()
        for path in (Path(__file__), TOOLS_DIR / 'native_evidence.py', PROBE_PATH)
    }
    record['configurationBefore'] = _snapshot()
    prompt = _prompt(args.platform)
    record['promptSha256'] = hashlib.sha256(prompt.encode()).hexdigest()
    token = ''
    try:
        token = _github_token()
        env = dict(os.environ, COPILOT_HOME=str(client_home))
        env['COPILOT_GITHUB_TOKEN'] = token
        safe, payloads, _ = run_native(project, args.copilot, prompt, base, env, timeout=420)

        calls = safe.get('calls') if isinstance(safe.get('calls'), list) else []
        observed_tools = sorted(
            {item.get('toolName') for item in calls if isinstance(item.get('toolName'), str)}
        )
        records = {
            'process': safe.get('process'),
            'calls': calls,
            'observedCompletedAlive': safe.get('observedCompletedAlive'),
            'mainSkillLoaded': safe.get('mainSkillLoaded'),
            'finalReportSha256': safe.get('finalReportSha256'),
            'finalStatus': safe.get('finalStatus'),
            'limits': safe.get('limits'),
        }
        records['toolPolicy'] = {
            'observedToolCount': len(observed_tools),
            'unexpectedToolCount': sum(1 for name in observed_tools if name not in ALLOWED_TOOLS),
            'onlyPermittedTools': all(name in ALLOWED_TOOLS for name in observed_tools),
            'pythonExecObserved': any(
                item.get('mcpToolName') == 'python_exec' for item in calls if isinstance(item, dict)
            ),
            'skillNames': sorted(
                {item['skill'] for item in calls if isinstance(item, dict) and item.get('skill') in PERMITTED_SKILLS}
            ),
        }
        expected_code_hash = hashlib.sha256(_probe_code(args.platform).encode()).hexdigest()
        probe_calls = [
            call for call in calls
            if call.get('mcpToolName') == 'python_exec'
            and call.get('codeSha256') == expected_code_hash
            and call.get('status') == 'completed' and call.get('kernelState') == 'alive'
            and call.get('success') is True
        ]
        probe_counts = {call.get('executionCount') for call in probe_calls}
        execution_calls = [call for call in calls if call.get('mcpToolName') == 'python_exec']
        exact_execution = len(execution_calls) == len(probe_calls) == 1
        records['toolPolicy']['exactProbeExecuted'] = exact_execution
        records['toolPolicy']['executionCount'] = len(execution_calls)
        probe_payloads = [payload for payload in payloads if payload.get('executionCount') in probe_counts]
        accepted, rejected = _collect_probe(probe_payloads, args.platform)
        probe_validation = 'not-observed'
        if accepted:
            probe_validation = 'valid'
        elif rejected:
            probe_validation = 'invalid'
        records['probeObservation'] = {
            'validation': probe_validation,
            'observationCount': len(accepted),
            'rejectedCount': rejected,
            'observed': bool(accepted),
        }
        if accepted:
            facts = accepted[-1]['facts']
            limitations = accepted[-1]['limitations']
            probe_outcome, blockers = _classify(args.platform, facts)
            records['probeFacts'] = facts
            records['probeLimitations'] = limitations
        else:
            probe_outcome = None
            blockers = ['probe-invalid' if rejected else 'probe-not-observed']

        final_status = safe.get('finalStatus') if isinstance(safe.get('finalStatus'), dict) else {}
        agent_outcome = final_status.get('taskOutcome')
        if agent_outcome not in {'blocked', 'ready-for-next-step'}:
            agent_outcome = 'unknown'
        records['agentOutcome'] = agent_outcome
        records['probeOutcome'] = probe_outcome

        if probe_outcome is not None:
            if agent_outcome == 'unknown':
                outcome = probe_outcome
                source = 'probe-only'
                agree = None
            else:
                outcome = 'blocked' if 'blocked' in {agent_outcome, probe_outcome} else 'ready-for-next-step'
                source = 'agent+probe-conservative'
                agree = agent_outcome == probe_outcome
            if outcome == 'blocked' and not blockers:
                blockers = ['agent-reported-blocker']
        else:
            # No validated probe evidence: a truthful agent block may stand,
            # but prose alone can never establish readiness.
            outcome = 'blocked' if agent_outcome == 'blocked' else 'unknown'
            source = 'agent-only; probe-not-observed'
            agree = None
        if not exact_execution or not records['toolPolicy']['onlyPermittedTools']:
            outcome = 'blocked'
            source = 'execution-policy-violation'
            blockers = sorted(set(blockers + ['execution-policy-violation']))
        records['observedReadiness'] = outcome
        records['observedReadinessSource'] = source
        records['agentProbeAgree'] = agree
        records['blockers'] = blockers

        cleanup = []
        for key in ('runnerCleanup', 'runnerCleanupFinal'):
            value = (records['process'] or {}).get(key)
            if isinstance(value, list):
                cleanup.extend(item for item in value if isinstance(item, dict))
        records['runnerCleanupObserved'] = bool(cleanup) and all(
            item.get('observedExit') is True for item in cleanup
        ) and all(item.get('identityMismatch') is not True for item in cleanup)
        records['runnerCleanupEntries'] = len(cleanup)
        record.update(records)
    except Exception as error:
        record['error'] = {'type': type(error).__name__}
    finally:
        record['configurationAfter'] = _snapshot()
        record['configurationUnchanged'] = record['configurationBefore'] == record['configurationAfter']
        replacements = [
            (str(base), '$TASK_ROOT'),
            (str(Path(base).resolve()), '$TASK_ROOT'),
            (str(project), '$TARGET_PROJECT'),
            (str(PROBE_PATH), '$PROBE_PATH'),
            (str(TOOLS_DIR), '$TOOLS_DIR'),
            (str(Path.home()), '$HOME'),
        ]
        args.output.write_text(serialize(record, token, replacements))
        print(
            json.dumps(
                {
                    'platform': args.platform,
                    'evidence': str(args.output),
                    'qualification': record['qualification'],
                    'probeValidation': (record.get('probeObservation') or {}).get('validation'),
                    'observedReadiness': record.get('observedReadiness'),
                    'observedCompletedAlive': record.get('observedCompletedAlive'),
                    'runnerCleanupObserved': record.get('runnerCleanupObserved'),
                    'configurationUnchanged': record['configurationUnchanged'],
                    'errorType': (record.get('error') or {}).get('type'),
                },
                sort_keys=True,
            ),
            flush=True,
        )


if __name__ == '__main__':
    main()

"""Task-owned read-only platform prerequisite probe (throwaway verification support).

Intended to be executed only from inside the real amkernel python_exec tool:

    ns = {}
    exec(compile(open(path, encoding="utf-8").read(), path, "exec"), ns)
    print(json.dumps(ns["probe_json"]("android"), sort_keys=True))

It never starts a service, session or device, never installs anything and never
changes configuration. The only file it creates is a task-owned temporary
directory for the one-shot `devicectl --json-output` payload, removed before
returning. Output is a strict allowlist of booleans, counts, parsed version
numbers and canonical labels: no paths, commands, device identifiers, model
names, inventories, or raw error text.
"""
import json
import os
import re
import shutil
import socket
import subprocess
import tempfile

SCHEMA_VERSION = 1
PLATFORMS = ("android", "ios-simulator", "ios-device")

LIMITATIONS = frozenset(
    {
        "adb-binary-missing",
        "adb-server-not-preexisting",
        "android-target-counts-unknown",
        "device-inventory-unparseable",
        "devicectl-missing",
        "java-version-execution-unavailable",
        "sdk-root-missing",
        "simctl-missing",
        "simulator-inventory-unparseable",
        "xcode-not-selected",
    }
)


def _run(argv, timeout):
    """Run a read-only command; return (exitCode|None, stdout, stderr)."""
    try:
        completed = subprocess.run(
            [str(item) for item in argv],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            check=False,
        )
        return completed.returncode, completed.stdout or "", completed.stderr or ""
    except (OSError, subprocess.SubprocessError, ValueError):
        return None, "", ""


def _major_minor(text):
    match = re.search(r"(\d+)\.(\d+)", text)
    if not match:
        return None, None
    return int(match.group(1)), int(match.group(2))


def _java_major(text):
    match = re.search(r'version "(\d+)(?:\.(\d+))?', text)
    if not match:
        return None
    major = int(match.group(1))
    if major == 1 and match.group(2) is not None:
        major = int(match.group(2))
    return major


def _java_candidates():
    candidates = []
    seen = set()

    def add(path):
        if not path or not os.path.isfile(path) or not os.access(path, os.X_OK):
            return
        resolved = os.path.realpath(path)
        if resolved in seen:
            return
        seen.add(resolved)
        candidates.append(path)

    explicit = os.environ.get("JAVA_HOME")
    if explicit:
        add(os.path.join(explicit, "bin", "java"))
    add(shutil.which("java"))
    code, out, err = _run(["/usr/libexec/java_home", "-V"], 20)
    if code is not None:
        for line in (err + "\n" + out).splitlines():
            stripped = line.strip()
            if not stripped or not stripped[0].isdigit():
                continue
            # The tab-delimited final column is the home path and may contain spaces.
            match = re.search(r"(/[^\t]*)\s*$", stripped)
            if match:
                add(os.path.join(match.group(1), "bin", "java"))
    for bundled in (
        "/Applications/Android Studio.app/Contents/jbr/Contents/Home",
        "/Applications/Android Studio.app/Contents/jre/jdk/Contents/Home",
    ):
        add(os.path.join(bundled, "bin", "java"))
    return candidates


def _java_facts():
    candidates = _java_candidates()
    candidate_count = len(candidates)
    executed = 0
    succeeded = 0
    majors = []
    outcomes = {}
    for executable in candidates:
        code, out, err = _run([executable, "-version"], 10)
        executed += 1
        major = _java_major(err + out) if code == 0 else None
        if code == 0:
            succeeded += 1
        if major is not None:
            majors.append(major)
        outcomes[os.path.realpath(executable)] = (code == 0, major)
    default_executed = False
    default_major = None
    default_java = shutil.which("java")
    if default_java:
        state = outcomes.get(os.path.realpath(default_java))
        if state is None:
            code, out, err = _run([default_java, "-version"], 10)
            executed += 1
            candidate_count += 1
            if code == 0:
                succeeded += 1
            major = _java_major(err + out) if code == 0 else None
            if major is not None:
                majors.append(major)
            state = (code == 0, major)
        default_executed, default_major = state
    return {
        "candidates": candidate_count,
        "executed": executed,
        "succeeded": succeeded,
        "majorVersions": sorted(set(majors)),
        "defaultExecuted": default_executed,
        "defaultMajor": default_major,
    }


def _sdk_and_adb_facts():
    env_values = [os.environ.get("ANDROID_HOME"), os.environ.get("ANDROID_SDK_ROOT")]
    env_roots = [value for value in env_values if value and os.path.isdir(value)]
    default_root = os.path.join(os.path.expanduser("~"), "Library", "Android", "sdk")
    default_present = os.path.isdir(default_root)
    path_adb = shutil.which("adb")
    inferred_root = None
    if path_adb:
        parent = os.path.dirname(os.path.realpath(path_adb))
        if os.path.basename(parent) == "platform-tools":
            inferred_root = os.path.dirname(parent)
    roots = []
    seen_roots = set()
    for root in env_roots + ([default_root] if default_present else []) + ([inferred_root] if inferred_root else []):
        resolved = os.path.realpath(root)
        if resolved not in seen_roots:
            seen_roots.add(resolved)
            roots.append(root)
    root_present = bool(roots)
    adb = None
    for root in roots:
        candidate = os.path.join(root, "platform-tools", "adb")
        if os.path.isfile(candidate) and os.access(candidate, os.X_OK):
            adb = candidate
            break
    if adb is None and path_adb:
        adb = path_adb
    version_executed = False
    version_parsed = False
    major = minor = build = None
    if adb:
        code, out, err = _run([adb, "version"], 15)
        version_executed = code is not None
        match = re.search(r"(\d+)\.(\d+)\.(\d+)", out + err)
        if code == 0 and match:
            version_parsed = True
            major, minor, build = (int(match.group(1)), int(match.group(2)), int(match.group(3)))
    return (
        {
            "envConfigured": bool(env_roots),
            "defaultRootPresent": default_present,
            "rootPresent": root_present,
        },
        {
            "present": adb is not None,
            "versionExecuted": version_executed,
            "versionParsed": version_parsed,
            "major": major,
            "minor": minor,
            "build": build,
        },
    )


def _recv_exact(connection, size):
    chunks = []
    remaining = size
    while remaining > 0:
        chunk = connection.recv(remaining)
        if not chunk:
            raise OSError("closed")
        chunks.append(chunk)
        remaining -= len(chunk)
    return b"".join(chunks)


def _adb_targets():
    """Query a pre-existing adb server over its socket protocol; never starts/restarts it."""
    try:
        connection = socket.create_connection(("127.0.0.1", 5037), timeout=2)
    except OSError:
        return False, None
    try:
        payload = b"host:devices"
        connection.sendall(("%04x" % len(payload)).encode("ascii") + payload)
        if _recv_exact(connection, 4) != b"OKAY":
            return False, None
        length = int(_recv_exact(connection, 4), 16)
        body = _recv_exact(connection, length).decode("utf-8", "replace")
    except (OSError, ValueError):
        return False, None
    finally:
        try:
            connection.close()
        except OSError:
            pass
    total = device = emulator = offline = unauthorized = other = 0
    for line in body.splitlines():
        parts = line.strip().split("\t")
        if len(parts) < 2:
            continue
        serial, state = parts[0].strip(), parts[1].strip()
        if not serial or not state:
            continue
        total += 1
        if state == "device":
            if serial.startswith("emulator-"):
                emulator += 1
            else:
                device += 1
        elif state == "offline":
            offline += 1
        elif state == "unauthorized":
            unauthorized += 1
        else:
            other += 1
    return True, {
        "known": True,
        "total": total,
        "device": device,
        "emulator": emulator,
        "offline": offline,
        "unauthorized": unauthorized,
        "other": other,
    }


def _xcode_facts():
    code, _, _ = _run(["xcode-select", "-p"], 10)
    select_executed = code is not None
    selected = code == 0
    build_executed = False
    version_parsed = False
    major = minor = None
    if selected:
        code, out, err = _run(["xcodebuild", "-version"], 30)
        build_executed = code is not None
        parsed = _major_minor(out + err)
        if code == 0 and parsed[0] is not None:
            version_parsed = True
            major, minor = parsed
    return {
        "selectExecuted": select_executed,
        "selected": selected,
        "buildExecuted": build_executed,
        "versionParsed": version_parsed,
        "major": major,
        "minor": minor,
    }


def _tool_present(name):
    code, _, _ = _run(["xcrun", "--find", name], 10)
    return code == 0


def _count(items, predicate):
    return sum(1 for item in items if predicate(item))


def _simulator_facts():
    xcode = _xcode_facts()
    simctl = {"present": _tool_present("simctl"), "listExecuted": False, "parseable": False}
    runtimes = {"total": None, "available": None, "unavailable": None}
    devices = {"total": None, "booted": None, "shutdown": None, "available": None, "unavailable": None}
    if simctl["present"]:
        code, out, err = _run(["xcrun", "simctl", "list", "--json"], 60)
        simctl["listExecuted"] = code is not None
        data = None
        if code == 0 and out.strip():
            try:
                data = json.loads(out)
            except (ValueError, TypeError):
                data = None
        if isinstance(data, dict):
            runtime_items = data.get("runtimes")
            device_map = data.get("devices")
            if isinstance(runtime_items, list) and isinstance(device_map, dict):
                simctl["parseable"] = True
                available = _count(
                    runtime_items,
                    lambda item: isinstance(item, dict) and item.get("isAvailable") is True,
                )
                runtimes = {
                    "total": len(runtime_items),
                    "available": available,
                    "unavailable": len(runtime_items) - available,
                }
                flat = []
                for entries in device_map.values():
                    if isinstance(entries, list):
                        flat.extend(item for item in entries if isinstance(item, dict))
                devices = {
                    "total": len(flat),
                    "booted": _count(flat, lambda item: item.get("state") == "Booted"),
                    "shutdown": _count(flat, lambda item: item.get("state") == "Shutdown"),
                    "available": _count(flat, lambda item: item.get("isAvailable") is True),
                    "unavailable": _count(flat, lambda item: item.get("isAvailable") is False),
                }
    return {"xcode": xcode, "simctl": simctl, "runtimes": runtimes, "devices": devices}


def _devicectl_facts():
    xcode = _xcode_facts()
    present = _tool_present("devicectl")
    devicectl = {
        "present": present,
        "listExecuted": False,
        "parseable": False,
        "countsKnown": False,
        "devices": {"total": None, "connected": None, "paired": None, "unavailable": None, "unknown": None},
    }
    if not present:
        return {"xcode": xcode, "devicectl": devicectl}
    temporary = tempfile.mkdtemp(prefix="amkernel-devicectl-")
    output = os.path.join(temporary, "devices.json")
    try:
        code, _, _ = _run(
            ["xcrun", "devicectl", "list", "devices", "--json-output", output], 60
        )
        devicectl["listExecuted"] = code is not None
        data = None
        try:
            with open(output, "r", encoding="utf-8") as handle:
                data = json.load(handle)
        except (OSError, ValueError, TypeError):
            data = None
        devices = None
        if isinstance(data, dict):
            result = data.get("result")
            if isinstance(result, dict) and isinstance(result.get("devices"), list):
                devices = result["devices"]
            elif isinstance(data.get("devices"), list):
                devices = data["devices"]
        if code == 0 and devices is not None:
            devicectl["parseable"] = True
            classified = {"connected": 0, "paired": 0, "unavailable": 0, "unknown": 0}
            for item in devices:
                if not isinstance(item, dict):
                    classified["unknown"] += 1
                    continue
                connection = item.get("connectionProperties")
                properties = item.get("deviceProperties")
                connection = connection if isinstance(connection, dict) else {}
                properties = properties if isinstance(properties, dict) else {}
                tunnel = connection.get("tunnelState")
                pairing = connection.get("pairingState")
                is_paired = properties.get("isPaired")
                services = properties.get("ddiServicesAvailable")
                if is_paired is True or pairing == "paired":
                    classified["paired"] += 1
                if tunnel == "connected":
                    classified["connected"] += 1
                elif tunnel in {"unavailable", "disconnected"} or services is False:
                    classified["unavailable"] += 1
                else:
                    classified["unknown"] += 1
            devicectl["countsKnown"] = True
            devicectl["devices"] = {
                "total": len(devices),
                "connected": classified["connected"],
                "paired": classified["paired"],
                "unavailable": classified["unavailable"],
                "unknown": classified["unknown"],
            }
    finally:
        shutil.rmtree(temporary, ignore_errors=True)
    return {"xcode": xcode, "devicectl": devicectl}


def probe_json(platform):
    if platform not in PLATFORMS:
        raise ValueError("unsupported platform")
    limitations = set()
    if platform == "android":
        java = _java_facts()
        sdk, adb = _sdk_and_adb_facts()
        listening, targets = _adb_targets()
        if not sdk["rootPresent"]:
            limitations.add("sdk-root-missing")
        if java["succeeded"] < 1:
            limitations.add("java-version-execution-unavailable")
        if not adb["present"]:
            limitations.add("adb-binary-missing")
        if not listening:
            limitations.add("adb-server-not-preexisting")
        if targets is None:
            limitations.add("android-target-counts-unknown")
        facts = {
            "java": java,
            "sdk": sdk,
            "adb": adb,
            "adbServer": {"preexistingListening": listening},
            "targets": targets,
        }
    elif platform == "ios-simulator":
        facts = _simulator_facts()
        if not facts["xcode"]["selected"]:
            limitations.add("xcode-not-selected")
        if not facts["simctl"]["present"]:
            limitations.add("simctl-missing")
        elif not facts["simctl"]["parseable"]:
            limitations.add("simulator-inventory-unparseable")
    else:
        facts = _devicectl_facts()
        if not facts["xcode"]["selected"]:
            limitations.add("xcode-not-selected")
        if not facts["devicectl"]["present"]:
            limitations.add("devicectl-missing")
        elif not facts["devicectl"]["parseable"]:
            limitations.add("device-inventory-unparseable")
    return {
        "schemaVersion": SCHEMA_VERSION,
        "platform": platform,
        "facts": facts,
        "limitations": sorted(limitations & LIMITATIONS),
    }
